def count_digits(x: int) -> int:
    """Return number of decimal digits in x."""
    if x < 0:
        raise ValueError("x must be non-negative")
    return len(str(x))

def find_Index(n: int) -> int:
    """
    Find the index k such that T_k is the smallest triangular number 
    with exactly n decimal digits.

    Returns k (1-based).
    """
    if n <= 0:
        raise ValueError("n must be a positive integer")

    # Start from k = 1 and go upwards until we find an n-digit triangular number
    k = 1
    while True:
        t = k * (k + 1) // 2
        if count_digits(t) == n:
            return k

        # Optional early break condition to avoid infinite loop in case of bug:
        # If we ever get a number with more than n digits, something is wrong.
        if count_digits(t) > n:
            raise RuntimeError(f"No triangular number found for {n} digits")

