def is_polite(n):
    def count_divisors(num):
        if num == 1:
            return 1
        div_count = 0
        i = 2
        while i * i <= num:
            if num % i == 0:
                exponent = 0
                temp_num = num // i
                while temp_num % i == 0:
                    exponent += 1
                    temp_num //= i
                div_count += (exponent + 1)
            i += 1
        if temp_num > 1:
            div_count += 2
        return div_count

    def is_perfect_square(num):
        sqrt = int(num ** 0.5)
        return sqrt * sqrt == num

    divisor_sum = sum(i for i in range(1, n + 1)) if n > 0 else 0

    while True:
        d_count = count_divisors(n)

        # Check first condition: number of divisors is a perfect square
        if not is_perfect_square(d_count):
            n += 1
            continue

        # Calculate sum of proper divisors (excluding the number itself)
        total_sum = divisor_sum + d_count - n

        # Second condition: sum of proper divisors must be greater than or equal to the number
        if total_sum < n:
            n += 1
            continue

        return n

if __name__ == "__main__":
    assert is_polite(7) == 11

