def normalize_tuple(t):
    """Converts a tuple into an immutable frozenset for order-independent comparison."""
    return frozenset(sorted(t))

def tuple_intersection(list1, list2):
    # Normalize all tuples in both lists and convert to sets of normalized elements
    set1 = {normalize_tuple(t) for t in list1}
    set2 = {normalize_tuple(t) for t in list2}

    # Compute the intersection
    result_set = set1 & set2

    return result_set

