def find_length(s: str) -> int:
    max_diff = 0
    current_sum = 0

    for char in s:
        if char == '1':
            current_sum -= 1
        else:
            current_sum += 1

        # Track maximum difference seen so far (absolute value of sum)
        diff = abs(current_sum)
        max_diff = max(max_diff, diff)

    return max_diff

