def find_length(s):
    max_diff = 0
    current_sum = 0

    # Treat '1' as +1 and '0' as -1 to maximize (count_ones - count_zeros)
    for char in s:
        if char == '1':
            current_sum += 1
        else:
            current_sum -= 1

        max_diff = max(max_diff, current_sum)

    # Now treat '0' as +1 and '1' as -1 to maximize (count_zeros - count_ones)
    current_sum = 0
    for char in s:
        if char == '0':
            current_sum += 1
        else:
            current_sum -= 1

        max_diff = max(max_diff, current_sum)

    return max_diff

